const input = $input.first().json;

const nutritionResults = input.nutrition;

let message = "🍱 FOOD ANALYSIS\n";
message += "====================\n\n";

const totals = {};

// Loop through each food component
for (const food of nutritionResults) {

    message += `🍽️ ${food.component}\n`;
    message += `Portion: ${food.portion_g} g\n`;
    message += `Food: ${food.food.name}\n`;
    message += `Food ID: ${food.food.food_id}\n\n`;

    message += "Nutrition:\n";

    // food.nutrition contains the actual nutrients
    for (const [nutrient, data] of Object.entries(food.nutrition)) {

        message += `${nutrient}: ${data.value.toFixed(2)} ${data.unit}\n`;

        // Add to totals
        if (!totals[nutrient]) {
            totals[nutrient] = {
                value: 0,
                unit: data.unit
            };
        }

        totals[nutrient].value += data.value;
    }

    message += "\n--------------------\n\n";
}


// Total nutrition
message += "📊 TOTAL NUTRITION\n";
message += "====================\n\n";

for (const [nutrient, data] of Object.entries(totals)) {

    message += `${nutrient}: ${data.value.toFixed(2)} ${data.unit}\n`;
}


return [
    {
        json: {
            message: message
        }
    }
];
